"""Additional curated demo recipes used to grow the local, filterable catalog."""

def ing(name, amount, unit="г", optional=False):
    return {"name": name, "amount": amount, "unit": unit, "optional": optional}

def recipe(rid, title, description, minutes, servings, tags, method, ingredients, steps, difficulty="Легко"):
    return {"id":rid,"title":title,"description":description,"minutes":minutes,"difficulty":difficulty,
            "servings":servings,"tags":tags,"method":method,"allergens":[],"ingredients":ingredients,
            "steps":steps,"source":"Демонстрационный рецепт."}


EXTRA_RECIPES=[]

