 ("broccoli-bake","Брокколи под сырной корочкой","Запечённые соцветия брокколи с молочной заливкой.","брокколи",250,"г","savoury",35),
 ("apple-crumble","Яблочный крамбл","Запечённые яблоки под хрустящей овсяной крошкой.","яблоко",2,"шт","crumble",35),
 ("cinnamon-rolls","Булочки с корицей","Мягкие дрожжевые рулетики с коричной начинкой.","корица",8,"г","yeast",75),
